float2 IntersectBox(float3 OriginWS, float3 DirectionWS, float OpaqueDistance)
{
    float3 OriginOS = TransformWorldToObject(OriginWS);
    float3 DirectionOS = mul((float3x3)UNITY_MATRIX_I_M, DirectionWS);
    if (any((abs(DirectionOS) < 1e-7) & (abs(OriginOS) > 0.5))) return 0;
    float3 InverseDirection = (step(0, DirectionOS) * 2 - 1) / max(abs(DirectionOS), 1e-7);
    float3 PlaneA = (-0.5 - OriginOS) * InverseDirection;
    float3 PlaneB = ( 0.5 - OriginOS) * InverseDirection;
    float3 NearFace = min(PlaneA,PlaneB), FarFace = max(PlaneA,PlaneB);
    float Enter = max(0, max(NearFace.x, max(NearFace.y, NearFace.z)));
    float Leave = min(OpaqueDistance, min(FarFace.x, min(FarFace.y, FarFace.z)));
    return float2(Enter,Leave);
}

float2 UV = GetNormalizedScreenSpaceUV(Input.positionCS);
float RawDepth = SampleSceneDepth(UV);
#if !UNITY_REVERSED_Z
    RawDepth = lerp(UNITY_NEAR_CLIP_VALUE, 1, RawDepth);
#endif
float3 OpaqueWS = ComputeWorldSpacePosition(UV, RawDepth, UNITY_MATRIX_I_VP);
float3 DirectionWS = -GetWorldSpaceNormalizeViewDir(Input.positionWS);
// Project the ray origin onto the camera plane for orthographic views.
float3 OriginWS = GetCameraPositionWS();
if (unity_OrthoParams.w > 0.5)
    OriginWS = Input.positionWS - DirectionWS * dot(Input.positionWS - OriginWS, DirectionWS);
float OpaqueDistance = max(0, dot(OpaqueWS - OriginWS, DirectionWS));
float2 Interval = IntersectBox(OriginWS, DirectionWS, OpaqueDistance);
if (Interval.y <= Interval.x) return 0;

dissolve.code:
float3 Frequency = max(_NoiseScale, 1e-6) * float3(1, max(_NoiseVerticalScale, 1e-4), 1);

float3 SamplePositionOS = TransformWorldToObject(SamplePositionWS);
float AlongZ = smoothstep(0, 1, SamplePositionOS.z + 0.5);
float Dissolve = lerp(saturate(_DissolveNegativeZ), saturate(_DissolvePositiveZ), AlongZ);
float Noise = SAMPLE_TEXTURE3D_LOD(_Noise3D, sampler_Linear_Mirror,
    (SamplePositionWS - _NoiseScroll.xyz * _Time.y) * Frequency, 0).r;
// At dissolve=0 all nonnegative noise values survive, so that face stays solid.
float Threshold = Dissolve - max(_DissolveSoftness, 0.001);
float Shape = smoothstep(Threshold, Dissolve, Noise);

height.code:
float TopMetresPerUnit = rcp(max(length(UNITY_MATRIX_I_M[1].xyz), 1e-6));

float BelowTop = max(0, 0.5 - SamplePositionOS.y) * TopMetresPerUnit;
float HeightFade = _TopFadeHeight <= 0 ? 1 : smoothstep(0, _TopFadeHeight, BelowTop);

edge.code:
float Edge = Dissolve <= 0 ? 0 :
    1 - smoothstep(0, max(_EdgeWidth, 0.001), max(0, Noise - Threshold));
// Weight edge colour by visible front-to-back contribution, not sample count.
EdgeContribution += Edge * exp(-OpticalDepth) * (1 - exp(-PointDensity));

float EdgeWeight = saturate(EdgeContribution / max(Opacity, 1e-5)) * saturate(_EdgeStrength);
return half4(lerp(_FogColor.rgb, _EdgeColor.rgb, EdgeWeight), Opacity * saturate(_FogColor.a));

accumulation.code:
int Count = clamp((int)_Samples, 8, 128);
float StepLength = (Interval.y - Interval.x) / Count;

float PointDensity = Shape * max(_Density, 0) * HeightFade * Remaining * StepLength;
OpticalDepth += PointDensity;
if (OpticalDepth > 4.60517) break; // Less than one percent transmittance remains.

float Opacity = 1 - exp(-OpticalDepth);
